from adr.dist import Normal, Mixture, dot, exp, softmax, minimum, maximum


def model(x):
    s1 = minimum(maximum(dot(x[[0, 2, 3, 5, 10, 12]], [-0.313746, -0.0857627, 0.0798065, -3.13955, 0.0820938, 0.0224774]) + dot(x[[16, 18, 20, 22, 23, 27]], [5.38512, 0.00571994, -0.00778091, 0.0820419, -0.0261675, 0.0258909]) + dot(x[[29, 30, 31, 32, 33, 36]], [-0.0879042, 0.049549, -0.000659702, 0.000245171, -0.000849512, 0.016805]) + dot(x[[39, 40, 42, 45, 46, 47]], [0.000974872, -0.0023617, -0.0920266, 3.28142, -5.00184, -0.0140594]) + dot(x[[49, 54, 62, 63, 66, 67]], [0.0869254, 0.147931, 0.0360923, -0.0312367, 3.8439, -0.0125792]) + dot(x[[68, 70, 72, 80]], [-0.0636611, 0.112201, 2.1374, 1.01066]), -2.24196), 45.7803)
    s2 = minimum(maximum(dot(x[[11, 12, 13, 14, 15, 21]], [0.0704642, 0.0123407, -0.0553932, -0.0184488, -2.68557, 0.145917]) + dot(x[[23, 29, 32, 52, 55, 57]], [-0.08674, -0.275772, -0.00171941, 0.177119, -3.1886, -0.0202652]) + dot(x[[58, 72, 76]], [0.226788, 9.98772, 11.8037]), 8.69996), 87.8776)
    w = softmax(s1 - s1, -4.31058 + 0.11195 * s1 + 0.0238175 * s2, -14.6678 + 0.597985 * s1 + -0.121846 * s2, -47.4469 + 1.86032 * s1 + -0.617192 * s2, -47.6583 + 2.87813 * s1 + -2.12519 * s2)
    return Mixture(w, [
        Normal(0.534723 + 0.0878154 * s1, exp(0.469582)),
        Normal(1.10221 + 0.279588 * s1, exp(1.43067)),
        Normal(-11.699 + 1.06303 * s1, exp(2.37115)),
        Normal(-172.887 + 6.38408 * s1, exp(2.81711)),
        Normal(-202.96 + 7.89092 * s1, exp(2.03713)),
    ])
